// WOODSTOVE — a cast-iron wood stove on stubby legs that fights with the fire in its firebox.
//   STRIKE   (attack)         the door swings open and flame licks out. Up: out the chimney. Down: a hot iron stamp. Charged: a fireball.
//   GIMMICK  (special)        CHIMNEY SMOKE: hold to stoke, then puff a burning smoke cloud that drifts up and back.
//   RECOVERY (up + special)   flips over and smoke-rockets upward, steerable.
//   GRAB     (grab)           stuffs them in the firebox and fires them out the chimney.
export default function make(api) {
  const { hb, cap, key, mv, throwMove, spawnProjectile, spriteAnims, spriteLoops, B } = api;

  const stats = {
    weight: 128, walk: 2.2, run: 3.9, dashInit: 4.6, airSpeed: 3.2, airAccel: 0.14,
    fallSpeed: 8.5, fastFall: 12.5, gravity: 0.6, shortHop: 6.5, fullHop: 9.5, doubleJump: 8.5,
    jumps: 2, wallJump: false, traction: 0.7, height: 128, width: 64, crouchHeight: 100, landLag: 6, ledgeReach: 40,
  };

  const P = (extra) => ({ a: {}, ...extra });
  const rest = P({});
  const strikePoses = (total, hit, lean, extra = {}) => [
    key(0, P({ rot: -lean * 0.5, sx: 0.97, sy: 1.03, ...extra })),
    key(hit, P({ rot: lean, sx: 1.08, sy: 0.95, ...extra })),
    key(Math.min(total - 1, hit + 6), P({ rot: lean * 0.8, sx: 1.03, sy: 0.98, ...extra })),
    key(total, rest),
  ];
  const FIRE = { fx: "fire" };

  // THE STRIKE: flame licks out of the firebox grate (about 40 units up), short range, 11 damage.
  const STRIKE = { total: 30, hit: 8, active: 4, damage: 11, r: 17 };
  const aim = (id, dir, opts = {}) => {
    const s = { ...STRIKE, ...opts };
    const start = dir === "u" ? [4, -88] : dir === "b" ? [-18, -40] : dir === "d" ? [46, -32] : [20, -40];
    const end = dir === "u" ? [2, -128] : dir === "b" ? [-62, -40] : dir === "d" ? [48, -2] : [62, -40];
    const angle = dir === "u" ? 88 : dir === "d" ? 30 : 40;
    const lean = dir === "u" ? -4 : dir === "b" ? -10 : dir === "d" ? 8 : 10;
    const extra = dir === "d" ? { sy: 0.92, dy: 4 } : dir === "u" ? { sy: 1.06 } : {};
    const cell = dir === "u" ? "atk-up" : dir === "d" ? "atk-down" : "atk-fwd";
    return mv(id, s.total, [cap([s.hit, s.hit + s.active - 1], start[0], start[1], end[0], end[1], s.r, s.damage, angle, s.base ?? 40, s.growth ?? 85, { ...FIRE, ...(s.hb ?? {}) })],
      strikePoses(s.total, s.hit, lean, extra), { cell, cellFlip: dir === "b", ...(s.mv ?? {}) });
  };
  // GRAB: the door hoovers them in; every throw leaves out the chimney, tilted the way you hold
  const GRAB = { total: 40, hit: 8, damage: 10 };
  const toss = (id, angle, base, growth, pose) => throwMove(id, 40, 20, GRAB.damage, angle, base, growth,
    [key(0, P({ sx: 1.06 })), key(8, P({ rot: -4, sx: 0.94, sy: 1.06 })), key(14, P({ rot: 4, sx: 0.94, sy: 1.06 })), key(20, P(pose)), key(40, rest)]);

  const moves = {
    jab1: aim("jab1", "f", { total: 22, hit: 6, damage: 7, mv: { iasa: 17 } }),
    ftilt: aim("ftilt", "f"),
    dashAttack: aim("dashAttack", "f", { total: 40, hit: 10, damage: 11, mv: { motion: [[1, 5, 0], [12, 2, 0], [22, 0, 0]] } }),
    nair: aim("nair", "f", { total: 30, hit: 7, damage: 9, mv: { aerial: true, landingLag: 12 } }),
    fair: aim("fair", "f", { mv: { aerial: true, landingLag: 14 } }),
    bair: aim("bair", "b", { damage: 12, mv: { aerial: true, landingLag: 14 } }),
    utilt: aim("utilt", "u", { damage: 10 }),
    uair: aim("uair", "u", { damage: 10, mv: { aerial: true, landingLag: 12 } }),
    dtilt: aim("dtilt", "d", { damage: 10 }),
    dair: aim("dair", "d", { total: 42, hit: 13, damage: 13, hb: { spike: true }, mv: { aerial: true, landingLag: 20 } }),
    // charged: the whole firebox roars and a fireball bursts out, hottest at the tip
    fsmash: mv("fsmash", 56, [
      hb([17, 20], 96, -42, 26, 20, 38, 55, 100, { fx: "fire", priority: 0 }),
      cap([17, 22], 20, -42, 80, -42, 24, 15, 40, 45, 88, { ...FIRE, priority: 1 }),
    ], strikePoses(56, 17, 14, { sx: 1.04 }), { smash: true, cell: "atk-fwd", fx: "quake" }),
    usmash: aim("usmash", "u", { total: 52, hit: 15, active: 6, damage: 18, r: 24, base: 48, growth: 98, mv: { smash: true } }),
    dsmash: mv("dsmash", 54, [
      cap([16, 19], 10, -10, 70, -6, 22, 16, 30, 48, 90, { ...FIRE, group: 0 }),
      cap([22, 25], -10, -10, -70, -6, 22, 16, 30, 48, 90, { ...FIRE, group: 1 }),
    ], [key(0, P({ sy: 1.06 })), key(16, P({ rot: 10, sx: 1.1, sy: 0.88 })), key(22, P({ rot: -10, sx: 1.1, sy: 0.88 })), key(54, rest)], { smash: true, cell: "atk-down", fx: "quake" }),
    grab: mv("grab", GRAB.total, [hb([GRAB.hit, GRAB.hit + 2], 44, -42, 26, 0, 0, 0, 0, { grab: true })], strikePoses(GRAB.total, GRAB.hit, 8), { isGrab: true }),
    dashGrab: mv("dashGrab", 46, [hb([10, 12], 56, -42, 28, 0, 0, 0, 0, { grab: true })], strikePoses(46, 10, 12), { isGrab: true, motion: [[1, 4, 0], [10, 0, 0]] }),
    pummel: mv("pummel", 18, [], [key(0, P({ sx: 1.02 })), key(6, P({ rot: -4, sy: 1.08 })), key(12, P({ rot: 4, sy: 1.08 })), key(18, P({ sx: 1.02 }))]),
    uthrow: toss("uthrow", 90, 70, 94, { sy: 1.16, sx: 0.92 }),
    fthrow: toss("fthrow", 76, 62, 80, { sy: 1.12, rot: 8 }),
    bthrow: toss("bthrow", 104, 62, 80, { sy: 1.12, rot: -8 }),
    dthrow: toss("dthrow", 84, 45, 50, { sy: 0.86, sx: 1.12 }),
    // GIMMICK, CHIMNEY SMOKE: hold to stoke, then a burning puff out of the chimney
    nspecial: mv("nspecial", 48, [], stokePoses(48, 0), { hook: "puff", cell: "atk-up" }),
    sspecial: mv("sspecial", 48, [], stokePoses(48, 8), { hook: "cough", cell: "atk-fwd" }),
    dspecial: mv("dspecial", 56, [], stokePoses(56, 0), { hook: "hang", cell: "atk-up" }),
    // RECOVERY: tips over, chimney down, and a smoke column rockets it up
    uspecial: mv("uspecial", 72, [cap([8, 20], 0, 10, 0, 70, 26, 8, 80, 50, 60, { fx: "energy" })],
      [key(0, P({ sy: 0.86, sx: 1.1 })), key(7, P({ rot: 180 })), key(46, P({ rot: 180, sy: 1.1 })), key(60, P({ rot: 20 })), key(72, rest)],
      { hook: "rocket", helpless: true, ledgeOk: true, cell: "jump" }),
    ledgeAttack: aim("ledgeAttack", "f", { total: 40, hit: 12, damage: 9 }),
    getupAttack: mv("getupAttack", 44, [cap([12, 15], 10, -30, 62, -30, 20, 7, 45, 40, 60, { ...FIRE, group: 0 }), cap([20, 23], -10, -30, -62, -30, 20, 7, 45, 40, 60, { ...FIRE, group: 1 })], [key(0, rest), key(12, P({ rot: 10 })), key(20, P({ rot: -10 })), key(44, rest)]),
    taunt: mv("taunt", 60, [], [key(0, rest), key(15, P({ sy: 1.12, sx: 0.94 })), key(22, P({ sy: 0.92, sx: 1.08 })), key(38, P({ sy: 1.12, sx: 0.94 })), key(60, rest)], { cell: "atk-up" }),
  };

  function stokePoses(total, lean) {
    return [key(0, P({ sy: 0.94, sx: 1.05 })), key(10, P({ rot: -2, sy: 0.9, sx: 1.08 })), key(20, P({ rot: 2, sy: 0.9, sx: 1.08 })), key(21, P({ rot: lean, sy: 1.14, sx: 0.94 })), key(32, P({ rot: lean * 0.5 })), key(total, rest)];
  }

  // hold special on frames 1..20 to stoke (up to 60 frames); the puff grows bigger, slower and hotter
  const smoke = (mode) => ({ state, f, input }) => {
    if (f.frame <= 20 && f.special.stoke < 60 && (input.b & B.SPECIAL)) {
      f.special.stoke++;
      f.special.heat = Math.max(f.special.heat, (f.special.stoke / 60) * 100);
      if (f.frame === 20) f.frame = 19;
      return;
    }
    if (f.frame !== 21) return;
    const t = f.special.stoke / 60;
    f.special.stoke = 0;
    if (f.special.cooldown > 0) return;
    const mf = f.moveFacing;
    const r = 22 + t * 26;
    const box = { frames: [0, 999], x: 0, y: 0, r, damage: 5 + Math.floor(t * 9), angle: 70, base: 35, growth: 60 + t * 35, fx: "fire" };
    const life = 150 + Math.floor(t * 60);
    if (mode === "cough") spawnProjectile(state, f, "smoke", f.x + mf * 40, f.y - 44, mf * (2.8 - t * 1.2), 0, life, box, { g: 0 });
    else if (mode === "hang") spawnProjectile(state, f, "smoke", f.x, f.y - 110, 0, -0.2, life + 60, { ...box, r: r + 10 }, { g: 0 });
    else spawnProjectile(state, f, "smoke", f.x + mf * 4, f.y - 100, -mf * (1.1 - t * 0.5), -(0.8 - t * 0.4), life, box, { g: 0 });
    f.special.cooldown = 80 + Math.floor(t * 60);
  };

  return {
    id: "woodstove",
    name: "WOODSTOVE",
    tagline: "Cast iron. Always on. Please do not touch the front.",
    stats,
    moves,
    rig: { bones: [], anims: spriteAnims(), loops: spriteLoops },
    palette: { colors: { marker: "#e0482a" }, accent: "marker", outline: "#1e1c1a" },
    special: () => ({ stoke: 0, heat: 0, cooldown: 0 }),
    hooks: {
      puff: smoke("puff"),
      cough: smoke("cough"),
      hang: smoke("hang"),
      rocket: ({ f, input }) => {
        if (f.frame === 8) { f.grounded = false; f.platform = -1; f.usedUpSpecial = true; }
        if (f.frame >= 8 && f.frame <= 46) {
          f.vy = -10 + (f.frame - 8) * 0.2;
          f.vx = (input.x / 100) * 5;
        }
      },
    },
    onFrame: ({ f }) => {
      if (f.special.heat > 0) f.special.heat = Math.max(0, f.special.heat - 0.4);
      if (f.special.cooldown > 0) f.special.cooldown--;
    },
    meters: [{ label: "HEAT", color: "#ff8a20", get: (f) => f.special.heat / 100 }],
    visual: (f) => ({ glow: f.special.heat / 100 }),
  };
}
